"use client"

import type { ColumnDef } from "@/lib/feature-kit/data-table"
import { DataTable, DataTableColumnHeader } from "@/lib/feature-kit/data-table"
import { ContentPageHeader, DashboardShell } from "@/lib/feature-kit/layout"
import { AlertCircle, Inbox, RefreshCw } from "lucide-react"
import { useMemo, useState } from "react"

import { BlockPageRoot } from "@/components/blocks/block-page-root"
import { LayoutShellSidebarSlots } from "@/components/examples/layout/shell/layout-shell-shared"
import { type DemoPerson, demoPeople } from "@/components/examples/table/demo-rows"
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

const slots = LayoutShellSidebarSlots()

type StateVariant = "empty" | "loading" | "error"

const variants: { id: StateVariant; label: string }[] = [
	{ id: "empty", label: "Empty" },
	{ id: "loading", label: "Loading" },
	{ id: "error", label: "Error" },
]

export function AppStatesBlock() {
	const [variant, setVariant] = useState<StateVariant>("empty")

	const columns = useMemo<ColumnDef<DemoPerson>[]>(
		() => [
			{
				accessorKey: "name",
				header: ({ column }) => <DataTableColumnHeader column={column} title="Name" />,
			},
			{
				accessorKey: "email",
				header: ({ column }) => <DataTableColumnHeader column={column} title="Email" />,
			},
		],
		[],
	)

	return (
		<BlockPageRoot>
			<DashboardShell {...slots}>
				<ContentPageHeader
					description="Switch between empty, loading, and error presentations."
					title="Projects"
				/>
				<div className="mb-4 flex flex-wrap gap-2">
					{variants.map((item) => (
						<Button
							key={item.id}
							className={cn("h-8", variant === item.id && "bg-background shadow-sm")}
							size="sm"
							type="button"
							variant={variant === item.id ? "secondary" : "outline"}
							onClick={() => setVariant(item.id)}>
							{item.label}
						</Button>
					))}
				</div>
				{variant === "error" ? (
					<Alert variant="destructive">
						<AlertCircle className="size-4" aria-hidden />
						<AlertTitle>Could not load projects</AlertTitle>
						<AlertDescription className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
							<span>The request timed out. Check your connection and try again.</span>
							<Button size="sm" type="button" variant="outline">
								<RefreshCw className="size-4" aria-hidden />
								Retry
							</Button>
						</AlertDescription>
					</Alert>
				) : null}
				<div className="mt-4 min-h-[320px] overflow-hidden rounded-lg border bg-card">
					<DataTable
						columns={columns}
						data={variant === "empty" ? [] : demoPeople}
						displayKey="name"
						emptyState={{
							title: "No projects yet",
							description: "Create a project or import data to see rows here.",
							icons: [Inbox, Inbox, Inbox],
						}}
						isPending={variant === "loading"}
						selectionKey={(row) => row.id}
						syncUrl={false}
						tableId="block-states-table"
					/>
				</div>
			</DashboardShell>
		</BlockPageRoot>
	)
}

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"

/** Full-viewport root for block iframe previews. */
export function BlockPageRoot({ children, className }: { children: ReactNode; className?: string }) {
	return (
		<div className={cn("flex h-dvh min-h-0 flex-col overflow-hidden bg-background text-foreground", className)}>
			{children}
		</div>
	)
}

"use client"

import {
	DashboardAccountMenu,
	DashboardSidebarBrand,
	DashboardSidebarNav,
} from "@/lib/feature-kit/layout"
import { LayoutGrid } from "lucide-react"
import type { ReactNode } from "react"

import { SignOutDropdownMenuItem } from "@/lib/feature-kit/auth"
import { ThemeSelector } from "@/lib/feature-kit/theme"

import { workspaceNavGroups } from "./layout-demo-nav"

export function LayoutShellBrand() {
	return (
		<DashboardSidebarBrand
			href="/docs"
			logo={
				<div className="flex aspect-square size-8 items-center justify-center rounded-lg bg-primary text-primary-foreground">
					<LayoutGrid className="size-4" />
				</div>
			}
			subtitle="Playground"
			title="Feature Kits"
		/>
	)
}

export function LayoutShellSidebarNav() {
	return <DashboardSidebarNav groups={workspaceNavGroups} />
}

export function LayoutShellAccountMenu({
	user = { name: "Demo User", email: "demo@featurekit.dev" },
}: {
	user?: { name: string; email: string; image?: string | null }
}) {
	return (
		<DashboardAccountMenu signOutItem={<SignOutDropdownMenuItem />} user={user} />
	)
}

export function LayoutShellHeaderActions() {
	return <ThemeSelector label="Theme" />
}

export function LayoutShellSidebarFooter({ user }: { user?: { name: string; email: string } }) {
	return <LayoutShellAccountMenu {...(user ? { user } : {})} />
}

export function LayoutShellSidebarSlots(): {
	sidebarHeader: ReactNode
	sidebarContent: ReactNode
	sidebarFooter: ReactNode
	headerActions: ReactNode
} {
	return {
		sidebarHeader: <LayoutShellBrand />,
		sidebarContent: <LayoutShellSidebarNav />,
		sidebarFooter: <LayoutShellSidebarFooter />,
		headerActions: <LayoutShellHeaderActions />,
	}
}
